#include "qpm_csv.h"
#include <stdlib.h>
#include <string.h>

static int push_field(QpmCsvRow *row,const char *data,size_t len){char **grown;char *copy;if(!row)return -1;grown=(char**)realloc(row->fields,(row->count+1)*sizeof(*grown));if(!grown)return -2;row->fields=grown;copy=(char*)malloc(len+1);if(!copy)return -2;memcpy(copy,data,len);copy[len]='\0';row->fields[row->count++]=copy;return 0;}
void QpmCsv_FreeRow(QpmCsvRow *row){size_t i;if(!row)return;for(i=0;i<row->count;i++)free(row->fields[i]);free(row->fields);row->fields=NULL;row->count=0;}
int QpmCsv_ParseLine(const char *line,char delimiter,QpmCsvRow *row){size_t i=0,len;char *field;size_t used=0,cap=64;int quoted=0;if(!line||!row||delimiter=='\0')return -1;row->fields=NULL;row->count=0;field=(char*)malloc(cap);if(!field)return -2;len=strlen(line);while(1){char c=i<len?line[i]:'\0';if(quoted){if(c=='"'&&i+1<len&&line[i+1]=='"'){c='"';i+=2;}else if(c=='"'){quoted=0;i++;continue;}else if(c=='\0'){free(field);QpmCsv_FreeRow(row);return -3;}else{i++;}}else{if(c=='"'&&used==0){quoted=1;i++;continue;}if(c==delimiter||c=='\0'||c=='\r'||c=='\n'){int r=push_field(row,field,used);if(r){free(field);QpmCsv_FreeRow(row);return r;}used=0;if(c==delimiter){i++;continue;}break;}i++;}if(used+2>cap){char *g;cap*=2;g=(char*)realloc(field,cap);if(!g){free(field);QpmCsv_FreeRow(row);return -2;}field=g;}field[used++]=c;}free(field);return 0;}
int QpmCsv_ReadFile(const char *path,char delimiter,QpmCsvRowCallback callback,void *userData){FILE *f;char *line=NULL;size_t cap=0,used=0,rowIndex=0;int ch,status=0;if(!path||!callback)return -1;f=fopen(path,"rb");if(!f)return -2;while((ch=fgetc(f))!=EOF){if(used+2>cap){size_t next=cap?cap*2:512;char*g=(char*)realloc(line,next);if(!g){status=-3;goto done;}line=g;cap=next;}line[used++]=(char)ch;if(ch=='\n'){QpmCsvRow row;line[used]='\0';status=QpmCsv_ParseLine(line,delimiter,&row);if(status)goto done;status=callback(&row,rowIndex++,userData);QpmCsv_FreeRow(&row);used=0;if(status)goto done;}}
if(used){QpmCsvRow row;if(used+1>cap){char*g=(char*)realloc(line,used+1);if(!g){status=-3;goto done;}line=g;}line[used]='\0';status=QpmCsv_ParseLine(line,delimiter,&row);if(!status){status=callback(&row,rowIndex,userData);QpmCsv_FreeRow(&row);}}
done: free(line);fclose(f);return status;}
int QpmCsv_WriteField(FILE *file,const char *value,char delimiter){const char*p;int quote=0;if(!file||!value)return -1;for(p=value;*p;p++)if(*p==delimiter||*p=='"'||*p=='\r'||*p=='\n'){quote=1;break;}if(quote&&fputc('"',file)==EOF)return -2;for(p=value;*p;p++){if(*p=='"'&&fputc('"',file)==EOF)return -2;if(fputc(*p,file)==EOF)return -2;}if(quote&&fputc('"',file)==EOF)return -2;return 0;}
int QpmCsv_WriteRow(FILE *file,const char *const*fields,size_t count,char delimiter){size_t i;if(!file||(!fields&&count))return -1;for(i=0;i<count;i++){if(i&&fputc(delimiter,file)==EOF)return -2;if(QpmCsv_WriteField(file,fields[i]?fields[i]:"",delimiter))return -2;}return fputc('\n',file)==EOF?-2:0;}
int QpmCsv_AppendRow(const char *path,const char *const*fields,size_t count,char delimiter){FILE*f;int r;if(!path)return -1;f=fopen(path,"ab");if(!f)return -2;r=QpmCsv_WriteRow(f,fields,count,delimiter);if(fclose(f)!=0&&r==0)r=-2;return r;}
